                <StartupSplash />
            ) : (
                <MainWindow
                    auth={auth}
                    initialProjectOpenResolution={bootstrap.projectOpenResolution}
                    toolbarAction={(
                        <RemoteControlButton />
                    )}
                />
            )}
        </AppThemeProvider>
    )
}

