    getGithubAccessToken: () => githubAuthService.getAccessToken(),
    initializeAgentCapabilities: () => agentCapabilitiesService.initialize(),
    refreshStartupModelCatalogs: () => agentCapabilitiesService.refreshStartupCatalogs(
